// ————— Retention ladder —————
// vocab-retention-model-v1.md §2. Days to the next review, by stage.
// Shape is evidence-based (distribute, widen, widen a lot, expand rather than
// hold equal). The specific numbers are starting constants and want tuning.
const LADDER = [1, 3, 7, 16, 35, 90, 180];
const DAY = 86400000;
const SKIP_SENTENCE_FROM_VISIT = 3;      // §6.6

const now = () => Date.now();
const blank = () => ({ written: [], exposures: 0, sentences: 0, visits: 0, stage: -1, due: 0, log: [] });

// ————— Kana-only entry state (Session 10) —————
// A word with no kanji can never be pulled in by the kanji schedule, so before
// this existed パン and バス sat in WORDS permanently invisible. Decision
// (Session 10, Lloyd): a kana-only word enters when EITHER its grammar step has
// been started OR its katakana-track trigger lesson (kt, preferring CC/SB
// lessons) has been touched — whichever fires first.
// Module-level rather than state: loaded once at mount before `ready` flips,
// and neither store can change while this module is the one on screen.
let KATA_WALKED = new Set();     // every katakana character the learner has walked
let KATA_STARTED = new Set();    // katakana-module lesson ids with any progress
let GRAMMAR_STARTED = new Set(); // grammar point ids with any progress
// Grammar points the learner has FINISHED, by the grammar module's own
// definition of done ((quizBest ≠ null or studied) and practiced). This is
// what flips a verb form from a reference row into a question — reached is
// not enough; the quiz tests what a completed lesson taught.
let GRAMMAR_DONE = new Set();

// ————— Ruby —————
// Furigana is the GENERAL rendering mechanism, not an exception marker
// (Session 4 Decision 4; wired into the grammar module in Session 6). A word
// wears its reading until every kanji in it is learned, then quietly loses it —
// that loss is the promotion event. Same markup as the grammar and kanji
// modules so the three look identical.
//
// WHOLE-WORD ruby, not per-character. Aligning a reading to individual kanji
// needs okurigana alignment (the tokenizer job, not built), and getting it
// wrong puts the wrong kana over the wrong character. Whole-word is always
// correct, and it is what the grammar module already does.
//
// It is also REQUIRED for jukujikun: 今日 きょう does not split into 今 + 日 at
// all, so per-character ruby would be actively wrong there (Kanji display
// pipeline row, Jul 28 2026).
function needsRuby(word, known) {
  const all = [...(word.k || []), ...(word.u || [])];
  if (all.length) return !all.every((c) => known.includes(c)); // any unlearned kanji → ruby
  // Kana-only: a katakana word wears its HIRAGANA reading until the katakana
  // track has walked every character in it (Session 10) — the same "furigana as
  // the general rendering mechanism" rule, one script over. Hiragana gates
  // Stage 1, so the ruby is always readable. ー sits outside ァ-ヶ and never
  // gates (it is never individually walked).
  const kata = [...word.w].filter((c) => c >= "ァ" && c <= "ヶ");
  return kata.length > 0 && !kata.every((c) => KATA_WALKED.has(c));
}
function WordText({ word, known, size = 22, rt = ".5em" }) {
  const show = needsRuby(word, known) && word.r;
  if (!show) return <span style={{ font: `${size / 16}rem ${T.jpFont}` }}>{word.w}</span>;
  return (
    <ruby style={{ fontFamily: T.jpFont, fontSize: `${size / 16}rem`, rubyPosition: "over" }}>
      {word.w}<rt style={{ fontSize: rt, color: T.sub }}>{word.r}</rt>
    </ruby>
  );
}

// ————— Word helpers —————
function unlockedKanji(word, known) {
  return (word.k || []).filter((c) => known.includes(c));
}
function isComplete(word, known) {
  // Fully writable: every kanji it has is taught AND learned. Words containing
  // characters the syllabus never teaches (u[]) can never complete in Stage 1.
  if ((word.u || []).length) return false;
  if (!(word.k || []).length) return false;
  return word.k.every((c) => known.includes(c));
}
function pendingWork(word, prog, known) {
  // Characters unlocked in the kanji module but not yet practised here — this is
  // what makes a word "return" (§6.4). Every return carries at least one.
  const un = unlockedKanji(word, known);
  return un.filter((c) => !prog.written.includes(c));
}
function isKanaOnly(word) { return !(word.k || []).length && !(word.u || []).length; }
function kanaEligible(word) {
  // Either trigger admits the word; neither blocks the other (Session 10).
  if (word.kt && KATA_STARTED.has(word.kt)) return true;
  const pts = word.s ? STEP_POINTS[word.s] : null;
  return !!pts && pts.some((id) => GRAMMAR_STARTED.has(id));
}

// ————— First-clear timestamps (Session 11) —————
// Every save stamps any array element, object key, or newly-set field that has
// no stamp yet, under progress._firstAt — for per-word entries this yields
// exactly the "word:written:字" times the then-vs-now moment needs
// (reward-system-design-v1.md). Nothing reads it yet. Stamps equal to
// _stampEpoch predate stamping. Prev-free by design: persist() has a stale
// closure over progress, so the stamper only consults existing stamps.
function stampFirsts(next) {
  const t = Date.now();
  const stamps = { ...(next._firstAt || {}) };
  for (const id of Object.keys(next)) {
    if (id.startsWith("_")) continue;
    const entry = next[id];
    if (!entry || typeof entry !== "object") continue;
    for (const field of Object.keys(entry)) {
      const v = entry[field];
      if (Array.isArray(v)) {
        for (const el of v) {
          const k = id + ":" + field + ":" + String(el);
          if (stamps[k] == null) stamps[k] = t;
        }
      } else if (v && typeof v === "object") {
        for (const kk of Object.keys(v)) {
          const k = id + ":" + field + ":" + kk;
          if (stamps[k] == null) stamps[k] = t;
        }
      } else if (v != null) {
        const k = id + ":" + field;
        if (stamps[k] == null) stamps[k] = t;
      }
    }
  }
  return { ...next, _firstAt: stamps, _stampEpoch: next._stampEpoch == null ? t : next._stampEpoch };
}

export default function VocabularyModule() {
  const [progress, setProgress] = useState({});
  const [known, setKnown] = useState([]);
  const [points, setPoints] = useState(0);
  const [ready, setReady] = useState(false);
  const [view, setView] = useState("today");     // today | review
  const [active, setActive] = useState(null);    // word being practised
  const [toast, setToast] = useState(null);
  const [markerQuiz, setMarkerQuiz] = useState(null); // {kind, t, words} — Session 11 markers
  const [formDrill, setFormDrill] = useState(null);   // {form, items} — Session 18 form drills

  useEffect(() => {
    (async () => {
      const [p, k, ap, g, kp] = await Promise.all([
        loadJSON(KEY, {}), loadJSON(KNOWN_KANJI_KEY, []), loadJSON(AP_KEY, 0),
        loadJSON(GRAMMAR_KEY, {}), loadJSON(KATA_KEY, {}),
      ]);
      setProgress(p || {});
      setKnown(Array.isArray(k) ? k : []);
      setPoints(typeof ap === "number" ? ap : 0);
      // Kana-only entry state — set before `ready` flips so the queue memo and
      // needsRuby see it on first render.
      GRAMMAR_STARTED = new Set(Object.keys(g || {}));
      GRAMMAR_DONE = new Set(Object.entries(g || {})
        .filter(([, pr]) => pr && (pr.quizBest != null || pr.studied) && pr.practiced)
        .map(([id]) => id));
      KATA_STARTED = new Set(Object.keys(kp || {}));
      KATA_WALKED = new Set(Object.values(kp || {}).flatMap(
        (m) => [...((m || {}).walked || []), ...((m || {}).traced || [])]));
      setReady(true);
    })();
  }, []);

  const get = useCallback((w) => progress[w] || blank(), [progress]);

  const persist = useCallback(async (next, apDelta) => {
    next = stampFirsts(next);
    setProgress(next);
    await saveJSON(KEY, next);
    if (apDelta) {
      setPoints((prev) => { const v = prev + apDelta; saveJSON(AP_KEY, v); return v; });
    }
  }, []);

  // ————— Queues —————
  // Content-driven work wins ties over the interval scheduler: it arrives with a
  // reason and new material, where a bare interval review arrives with neither.
  const { fresh, returning, due, older } = useMemo(() => {
    const fresh = [], returning = [], due = [], older = [];
    if (!ready) return { fresh, returning, due, older };
    for (const word of WORDS) {
      if (!word.s && !word.kt) continue;           // dictionary-only: not taught yet
      if (isKanaOnly(word)) {
        // No kanji schedule to ride — enters on its own triggers (Session 10).
        // This also un-strands hiragana-only bank words like いす, which the
        // kanji-driven queues could never admit either.
        if (!kanaEligible(word)) continue;
        const p = get(word.w);
        if (p.visits === 0) fresh.push({ word, pend: [] });
        else if (p.due && p.due <= now()) due.push({ word, pend: [] });
        else older.push({ word, pend: [] });
        continue;
      }
      const p = get(word.w);
      const pend = pendingWork(word, p, known);
      if (pend.length && p.visits === 0) fresh.push({ word, pend });
      else if (pend.length) returning.push({ word, pend });
      else if (p.visits > 0 && p.due && p.due <= now()) due.push({ word, pend: [] });
      else if (p.visits > 0) older.push({ word, pend: [] });
    }
    return { fresh, returning, due, older };
  }, [ready, progress, known, get]);

  // Guarded: progress now carries top-level _firstAt/_stampEpoch entries
  // (Session 11 first-clear timestamps), which are not word records.
  const encountered = useMemo(
    () => Object.values(progress).filter((p) => p && p.exposures > 0).length, [progress]);
  const practised = useMemo(
    () => Object.values(progress).filter((p) => p && Array.isArray(p.written) && p.written.length > 0).length, [progress]);

  // ————— Achievement markers (Session 11) —————
  // ENCOUNTER / SEMI-MASTERY (tracker row): accumulation thresholds. Crossing
  // one OFFERS a short check-in — user choice, never a gate — which pays
  // AP.marker per remembered word. progress._markers holds the highest
  // threshold already answered per kind; the "_" prefix keeps it clear of
  // first-clear stamping. Thresholds and pay are placeholders like all of AP.
  const MARKER_T = [10, 25, 50, 100, 150, 200];
  const markers = progress._markers || {};
  const pracDue = [...MARKER_T].reverse().find((t) => practised >= t && t > (markers.prac || 0));
  const encDue = [...MARKER_T].reverse().find((t) => encountered >= t && t > (markers.enc || 0));
  const offer = pracDue ? { kind: "prac", t: pracDue } : encDue ? { kind: "enc", t: encDue } : null;
  const recordMarker = (kind, t, ap) =>
    persist({ ...progress, _markers: { ...markers, [kind]: t } }, ap || 0);
  const startMarkerQuiz = (kind, t) => {
    const pool = WORDS.filter((x) => {
      const p = get(x.w);
      return kind === "prac"
        ? (Array.isArray(p.written) && p.written.length > 0)
        : p.exposures > 0;
    });
    setMarkerQuiz({ kind, t, words: [...pool].sort(() => Math.random() - 0.5).slice(0, 5) });
  };

  // ————— Completing a visit —————
  const finishVisit = useCallback(async (word, opts) => {
    const p = { ...get(word.w) };
    const un = unlockedKanji(word, known);
    const gained = un.filter((c) => !p.written.includes(c));
    let ap = 0;

    p.exposures += 1;
    p.visits += 1;
    if (opts.wrote) {
      p.written = Array.from(new Set([...p.written, ...un]));
      ap += AP.kanji * gained.length;
    }
    if (opts.sentence) { p.sentences += 1; ap += AP.sentence; }

    const wasComplete = (word.k || []).every((c) => p.written.includes(c)) && !(word.u || []).length;
    if (opts.wrote && wasComplete && !p.completed) { p.completed = true; ap += AP.complete; }

    // Advance the ladder. A content-driven return counts as a review — it IS one
    // (vocab-retention-model-v1.md §3), so it advances the stage exactly as an
    // interval review would, and no separate review is queued this cycle.
    p.stage = Math.min(p.stage + 1, LADDER.length - 1);
    p.due = now() + LADDER[Math.max(0, p.stage)] * DAY;
    p.log.push({ t: now(), via: gained.length ? "kanji" : "interval", wrote: !!opts.wrote });

    await persist({ ...progress, [word.w]: p }, ap);
    setActive(null);
    setToast(ap ? <span>+{ap} <KobanIcon size={12} />{p.completed && wasComplete ? " · word complete" : ""}</span> : null);
    setTimeout(() => setToast(null), 2200);
  }, [get, known, progress, persist]);

  const markUnlearned = useCallback(async (word) => {
    // Manual lapse to stage 0 (§6.8). A learner volunteering "I don't actually
    // know this" is better data than any scheduler's guess, and it catches the
    // false positive no SRS handles — recognised from context, not from memory.
    const p = { ...get(word.w) };
    p.stage = -1;
    p.due = now();
    p.written = [];
    p.completed = false;
    p.log.push({ t: now(), via: "unlearned" });
    await persist({ ...progress, [word.w]: p }, 0);
    setToast("Back in practice");
    setTimeout(() => setToast(null), 1800);
  }, [get, progress, persist]);

  if (!ready) return <Shell><p style={{ color: T.sub }}>Loading…</p></Shell>;

  if (active) {
    return (
      <Shell>
        <Practice
          word={active.word}
          pend={active.pend}
          prog={get(active.word.w)}
          known={known}
          onDone={(opts) => finishVisit(active.word, opts)}
          onBack={() => setActive(null)}
        />
      </Shell>
    );
  }

  if (formDrill) {
    return (
      <Shell>
        <FormDrill
          form={formDrill.form}
          items={formDrill.items}
          onBack={() => setFormDrill(null)}
          onDone={(right) => {
            const seen = progress._formsSeen || [];
            persist({ ...progress, _formsSeen: [...seen, formDrill.form.id] }, 0);
            setFormDrill(null);
            setToast(`${right} of ${formDrill.items.length} — the form travels`);
            setTimeout(() => setToast(null), 2200);
          }}
        />
      </Shell>
    );
  }

  if (markerQuiz) {
    return (
      <Shell>
        <MarkerQuiz
          quiz={markerQuiz}
          onBack={() => setMarkerQuiz(null)}
          onDone={(g) => {
            recordMarker(markerQuiz.kind, markerQuiz.t, g * AP.marker);
            setMarkerQuiz(null);
            setToast(g ? <span>+{g * AP.marker} <KobanIcon size={12} /></span> : "Marker noted");
            setTimeout(() => setToast(null), 2200);
          }}
        />
      </Shell>
    );
  }

  return (
    <Shell>
      <header style={{ marginBottom: 20 }}>
        <h1 style={{ font: `600 1.375rem ${T.uiFont}`, color: T.ink, margin: "0 0 4px" }}>Vocabulary</h1>
        <p style={{ font: `0.875rem ${T.uiFont}`, color: T.sub, margin: 0 }}>
          Words come back when there is more of them you can write.
        </p>
      </header>

      {/* Accumulation only — never a denominator (§6.1). */}
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 22 }}>
        <Stat label="encountered" value={encountered} />
        <Stat label="practised with" value={practised} />
        <Stat label={<KobanIcon size={11} />} value={points} accent />
      </div>

      {/* Marker offer (Session 11) — proposes, never disposes. */}
      {offer && (
        <div role="status" style={{
          background: T.noteBg, border: `1px solid ${T.note}`, borderRadius: 10,
          padding: "12px 16px", marginBottom: 22,
        }}>
          <div style={{ font: `600 0.875rem ${T.uiFont}`, color: T.ink }}>
            You have now {offer.kind === "prac" ? "practised with" : "met"} {offer.t} words.
          </div>
          <div style={{ font: `0.8125rem/1.5 ${T.uiFont}`, color: T.sub, marginTop: 2 }}>
            Fancy a two-minute check-in? Remembering pays <KobanIcon size={11} />. Skipping costs nothing.
          </div>
          <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
            <button onClick={() => startMarkerQuiz(offer.kind, offer.t)} style={{
              font: `600 0.8125rem ${T.uiFont}`, padding: "8px 14px", borderRadius: 8, cursor: "pointer",
              background: T.ink, color: T.sheet, border: `1px solid ${T.ink}`,
            }}>Sure — check me</button>
            <button onClick={() => recordMarker(offer.kind, offer.t, 0)} style={{
              font: `600 0.8125rem ${T.uiFont}`, padding: "8px 14px", borderRadius: 8, cursor: "pointer",
              background: "none", color: T.sub, border: `1px solid ${T.hairline}`,
            }}>Not now</button>
          </div>
        </div>
      )}

      {/* ————— Form drill offer (Session 18) —————
          A verb form whose grammar point flipped to done since the last drill
          gets one: six pool verbs, mixed rules, sampled at random. Offered,
          never forced; pays nothing (drills earn nothing, per the achievement
          row). _formsSeen in known-words-v1 remembers what was offered. */}
      {ready && (() => {
        const seen = progress._formsSeen || [];
        const fresh = FORMS.find((f) => GRAMMAR_DONE.has(f.pt) && !seen.includes(f.id));
        if (!fresh || formDrill || active || markerQuiz) return null;
        return (
          <div style={{
            background: T.noteBg, border: `1px solid ${T.note}`, borderRadius: 10,
            padding: "12px 16px", marginBottom: 22,
          }}>
            <div style={{ font: `600 0.875rem ${T.uiFont}`, color: T.ink }}>
              Your grammar finished the {fresh.label}.
            </div>
            <div style={{ font: `0.8125rem/1.5 ${T.uiFont}`, color: T.sub, marginTop: 2 }}>
              Six verbs from the pool, mixed conjugation rules — see if the form holds away from the lesson.
            </div>
            <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
              <button onClick={() => setFormDrill({ form: fresh, items: sampleDrill(fresh.id) })} style={{
                font: `600 0.8125rem ${T.uiFont}`, padding: "8px 14px", borderRadius: 8, cursor: "pointer",
                background: T.ink, color: T.sheet, border: `1px solid ${T.ink}`,
              }}>Drill it</button>
              <button onClick={() => persist({ ...progress, _formsSeen: [...seen, fresh.id] }, 0)} style={{
                font: `600 0.8125rem ${T.uiFont}`, padding: "8px 14px", borderRadius: 8, cursor: "pointer",
                background: "none", color: T.sub, border: `1px solid ${T.hairline}`,
              }}>Skip</button>
            </div>
          </div>
        );
      })()}

      <Tabs view={view} setView={setView}
            reviewCount={older.length} />

      {view === "today" ? (
        <>
          <Queue title="New" hint="A kanji in these just became yours — or you can just now read them."
                 items={fresh} onOpen={setActive} known={known} />
          <Queue title="More to practise" badge
                 hint="You can write more of these than you could last time."
                 items={returning} onOpen={setActive} known={known} />
          <Queue title="Due" hint="Keeping these warm."
                 items={due} onOpen={setActive} known={known} />
          {!fresh.length && !returning.length && !due.length && (
            <Empty>Nothing waiting. New words arrive as you learn their kanji, move through the grammar, or work the katakana track.</Empty>
          )}
        </>
      ) : (
        <Review items={older} known={known} onOpen={setActive} onUnlearn={markUnlearned} />
      )}

      {toast && (
        <div role="status" style={{
          position: "fixed", left: "50%", transform: "translateX(-50%)", bottom: 28,
          background: T.ink, color: T.sheet, padding: "10px 18px", borderRadius: 999,
          font: `600 0.875rem ${T.uiFont}`, boxShadow: "0 4px 14px rgba(0,0,0,.18)",
        }}>{toast}</div>
      )}
    </Shell>
  );
}

// ————— Marker check-in (Session 11) —————
// The ENCOUNTER / SEMI-MASTERY markers' short quiz. SEMI-MASTERY prompts the
// meaning and asks the learner to recall the word; ENCOUNTER prompts the word
// and asks for the meaning. Self-marked — honest enough for a check-in that
// was optional to begin with, and it keeps the flow to two taps per word.
function MarkerQuiz({ quiz, onDone, onBack }) {
  const [i, setI] = useState(0);
  const [revealed, setRevealed] = useState(false);
  const [got, setGot] = useState(0);
  const w = quiz.words[i];
  if (!w) return null;
  const isPrac = quiz.kind === "prac";
  const next = (ok) => {
    const g = got + (ok ? 1 : 0);
    if (i + 1 >= quiz.words.length) onDone(g);
    else { setGot(g); setI(i + 1); setRevealed(false); }
  };
  return (
    <div>
      <button className="btn-ghost" onClick={onBack} style={{ marginBottom: 14 }}>← Not now</button>
      <div style={{ background: T.sheet, border: `1px solid ${T.hairline}`, borderRadius: 10,
                    padding: 22, textAlign: "center" }}>
        <div style={{ font: `0.75rem ${T.uiFont}`, color: T.sub, marginBottom: 10 }}>
          check-in · {i + 1} of {quiz.words.length}
        </div>
        {isPrac
          ? <div style={{ font: `600 1.25rem ${T.uiFont}`, color: T.ink }}>{w.m}</div>
          : <div style={{ fontFamily: T.jpFont, fontSize: "2.125rem", color: T.ink }}>{w.w}</div>}
        {!revealed ? (
          <button onClick={() => setRevealed(true)} style={{
            font: `600 0.8125rem ${T.uiFont}`, padding: "9px 16px", borderRadius: 8, cursor: "pointer",
            background: T.ink, color: T.sheet, border: `1px solid ${T.ink}`, marginTop: 16,
          }}>{isPrac ? "Show the word" : "Show the meaning"}</button>
        ) : (
          <>
            <div style={{ marginTop: 12 }}>
              {isPrac
                ? <div style={{ fontFamily: T.jpFont, fontSize: "2.125rem", color: T.ink }}>{w.w}
                    <span style={{ fontSize: "0.9375rem", color: T.sub, marginLeft: 10 }}>{w.r}</span></div>
                : <div style={{ font: `600 1.125rem ${T.uiFont}`, color: T.ink }}>{w.m}
                    <span style={{ font: `0.875rem ${T.uiFont}`, color: T.sub, marginLeft: 10 }}>{w.r}</span></div>}
            </div>
            <div style={{ display: "flex", gap: 10, justifyContent: "center", marginTop: 16 }}>
              <button onClick={() => next(true)} style={{
                font: `600 0.8125rem ${T.uiFont}`, padding: "9px 16px", borderRadius: 8, cursor: "pointer",
                background: T.ok, color: T.sheet, border: `1px solid ${T.ok}`,
              }}>I had it</button>
              <button className="btn-ghost" onClick={() => next(false)} style={{
                font: `600 0.8125rem ${T.uiFont}`, padding: "9px 16px", borderRadius: 8, cursor: "pointer",
                background: "none", color: T.sub, border: `1px solid ${T.hairline}`,
              }}>Not yet</button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

// ————— Practice flow: see → write → sentence —————
// ————— Verb forms UI —————
// One row per form. Forms the grammar has FINISHED render as a question first
// — four choices, wrong answers built from the mistakes the grammar teaches
// against — and reveal on answer. Forms not yet finished are plain reference
// rows: the card always shows the forms (Lloyd's ruling), it just doesn't
// quiz what nothing has taught. N3 forms join the table when triggered.
function FormRow({ w, cls, form }) {
  const [state, setState] = useState(null); // null | "right" | "wrong"
  const correct = conjugate(w, cls, form.id);
  if (!correct) return null;
  const done = GRAMMAR_DONE.has(form.pt);
  const opts = useMemo(() => {
    if (!done) return null;
    const d = formDistractors(w, cls, form.id, correct);
    return [correct, ...d].sort(() => Math.random() - 0.5);
  }, [w, form.id, done, correct, cls]);
  return (
    <div style={{ display: "flex", alignItems: "baseline", gap: 10, padding: "7px 0", borderBottom: `1px solid ${T.hairline}`, flexWrap: "wrap" }}>
      <span style={{ font: `0.75rem ${T.uiFont}`, color: T.sub, minWidth: 128 }}>{form.label}</span>
      {!done ? (
        <span style={{ font: `1rem ${T.jpFont}` }}>{correct}</span>
      ) : state ? (
        <span style={{ font: `1rem ${T.jpFont}`, color: state === "right" ? T.ink : T.note }}>
          {correct}{state === "wrong" ? " ←" : ""}
        </span>
      ) : (
        <span style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
          {opts.map((o) => (
            <button key={o} className="btn-ghost" style={{ padding: "3px 10px", font: `0.9375rem ${T.jpFont}` }}
              onClick={() => setState(o === correct ? "right" : "wrong")}>{o}</button>
          ))}
        </span>
      )}
    </div>
  );
}
function FormsBlock({ word }) {
  const vd = VERB_DATA[word.w];
  if (!vd) return null;
  const visible = FORMS.filter((f) => !(f.n3 || f.n2) || GRAMMAR_STARTED.has(f.pt) || GRAMMAR_DONE.has(f.pt));
  const quizzed = visible.filter((f) => GRAMMAR_DONE.has(f.pt)).length;
  return (
    <Card title="Forms">
      <p style={{ ...p14, color: T.sub, fontSize: "0.8125rem" }}>
        {quizzed
          ? <>The forms your grammar has finished are questions now — that's the point. The rest are here to read.</>
          : <>Every form this verb takes, as the grammar teaches each one.</>}
      </p>
      {visible.map((f) => <FormRow key={f.id} w={word.w} cls={vd.cls} form={f} />)}
      {vd.cls === "godan-ru" && /[いえきけしせちてにねひへみめりれ]る$/.test(word.w) && (
        <Note>Looks Ichidan, isn't — this is one of the Godan exceptions from Go と Ichi. The wrong options above are exactly the mistake to unlearn.</Note>
      )}
    </Card>
  );
}

// ————— Form drill: a new form unlocked, prove it on six verbs —————
function FormDrill({ form, items, onDone, onBack }) {
  const [i, setI] = useState(0);
  const [picked, setPicked] = useState(null);
  const [right, setRight] = useState(0);
  const it = items[i];
  const opts = useMemo(
    () => [it.correct, ...formDistractors(it.w, it.cls, form.id, it.correct)].sort(() => Math.random() - 0.5),
    [i]);
  const next = () => {
    if (i + 1 < items.length) { setI(i + 1); setPicked(null); }
    else onDone(right); // right was settled when the last answer was picked
  };
  return (
    <div>
      <button onClick={onBack} style={linkBtn}>← later</button>
      <Card title={`New form: ${form.label}`}>
        <p style={p14}>Your grammar just finished this form. Six verbs from the pool, mixed rules — conjugate each one.</p>
        <div style={{ textAlign: "center", margin: "18px 0" }}>
          <span style={{ font: `2.125rem ${T.jpFont}` }}>{it.w}</span>
          <span style={{ font: `0.875rem ${T.uiFont}`, color: T.sub, marginLeft: 12 }}>→ {form.label}?</span>
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", justifyContent: "center" }}>
          {opts.map((o) => (
            <button key={o} className="btn-ghost" disabled={picked != null}
              style={{
                padding: "8px 14px", font: `1.0625rem ${T.jpFont}`,
                background: picked == null ? undefined : o === it.correct ? T.noteBg : undefined,
                borderColor: picked != null && o === it.correct ? T.note : undefined,
                opacity: picked != null && o !== it.correct && o !== picked ? 0.45 : 1,
              }}
              onClick={() => { setPicked(o); if (o === it.correct) setRight((r) => r + 1); }}>{o}</button>
          ))}
        </div>
        {picked != null && (
          <div style={{ textAlign: "center", marginTop: 14 }}>
            <p style={{ ...p14, color: T.sub }}>
              {picked === it.correct ? "Right." : <>It's <b style={{ font: `1rem ${T.jpFont}` }}>{it.correct}</b>.</>}
              {it.trap ? " (One of the Godan look-alikes.)" : ""}
            </p>
            <Primary onClick={next}>{i + 1 < items.length ? "Next" : "Finish"}</Primary>
          </div>
        )}
      </Card>
    </div>
  );
}

function Practice({ word, pend, prog, known, onDone, onBack }) {
  const [step, setStep] = useState("see");
  const [wrote, setWrote] = useState(false);
  const un = unlockedKanji(word, known);
  // Only characters that are BOTH unlocked and have stroke data can be traced.
  // 言 is unlocked-but-undrawable until its paths are authored.
  const traceable = un.filter((c) => STROKES[c]);
  const visit = (prog.visits || 0) + 1;
  const canSkipSentence = visit >= SKIP_SENTENCE_FROM_VISIT;

  return (
    <div>
      <button onClick={onBack} style={linkBtn}>← back</button>

      {/* The scene — a moment the learner will stand in, opening the word the
          way an arc's setting opens a grammar lesson. EN vignette plus one JP
          line; reused lines carry their grammar point in src, new ones are
          flagged for the reviewer. Always shown, never dismissible. */}
      {VOCAB_SCENES[word.w] && (
        <div style={{ margin: "14px 0 0", padding: "0 4px" }}>
          <p style={{ font: `0.875rem/1.7 ${T.uiFont}`, color: T.sub, margin: 0 }}>
            {VOCAB_SCENES[word.w].scene}
          </p>
          <p style={{ font: `1.0625rem/1.9 ${T.jpFont}`, color: T.ink, margin: "8px 0 0" }}>
            {VOCAB_SCENES[word.w].jp}
          </p>
          <p style={{ font: `0.8125rem ${T.uiFont}`, color: T.sub, margin: "2px 0 0" }}>
            {VOCAB_SCENES[word.w].en}
          </p>
        </div>
      )}

      <div style={{
        background: T.sheet, border: `1px solid ${T.hairline}`, borderRadius: 12,
        padding: "26px 22px", textAlign: "center", margin: "14px 0 18px",
      }}>
        <div style={{ color: T.ink, lineHeight: 1.9 }}>
          <WordText word={word} known={known} size={40} />
        </div>
        {word.r && !needsRuby(word, known) && (
          <div style={{ font: `1rem ${T.jpFont}`, color: T.sub, marginTop: 6 }}>{word.r}</div>
        )}
        {word.m && <div style={{ font: `0.9375rem ${T.uiFont}`, color: T.sub, marginTop: 4 }}>{word.m}</div>}
        {word.j && (
          <div style={{ font: `0.8125rem ${T.uiFont}`, color: T.note, marginTop: 10 }}>
            This word's reading belongs to the whole word, not to its characters separately.
          </div>
        )}
      </div>

      {step === "see" && (
        <Card title={visit === 1 ? "Meet this word" : "You can write more of this now"}>
          {/* A kanji unlocking is what BRINGS a word here. It says nothing about
              whether the learner knows the WORD — they may never have met it.
              So the copy introduces rather than congratulates. */}
          <p style={p14}>
            {visit === 1 ? (
              <>You may have seen this already, or you may be about to — it turns up
                around {stepShort(word.s)}. Either way, here it is properly.</>
            ) : (
              <>You met this one before. Since then you have learned{" "}
                <b style={{ font: `1.125rem ${T.jpFont}` }}>{pend.join("、")}</b>, so more of it
                is yours to write than last time.</>
            )}
          </p>
          {word.j && (
            <Note>
              The reading belongs to the whole word here, not to its characters one by one.
              Learn <b>{word.r}</b> as a unit — taking it apart will mislead you.
            </Note>
          )}
          <Primary onClick={() => setStep("write")}>Next</Primary>
        </Card>
      )}

      {/* Teaching notes, in the grammar module's four-field shape so the two
          modules speak with one voice. Only words carrying something the gloss
          cannot say have these — a plain noun's whole lesson IS its gloss, and
          manufacturing a paragraph for each would bury the ones worth reading.
          AI-AUTHORED, pending reviewer sign-off. */}
      {step === "see" && word.x && (
        <Card title="How it works">
          {word.x.what && <p style={p14}>{word.x.what}</p>}
          {word.x.build && (
            <p style={{ ...p14, marginTop: 10 }}>
              <b style={{ color: T.sub }}>Building it · </b>{word.x.build}
            </p>
          )}
          {word.x.when && (
            <p style={{ ...p14, marginTop: 10 }}>
              <b style={{ color: T.sub }}>When · </b>{word.x.when}
            </p>
          )}
          {word.x.watch && <Note><b>Watch out · </b>{word.x.watch}</Note>}
        </Card>
      )}

      {/* The micro anecdote — a fifth block, and deliberately its OWN card rather
          than a fifth field inside "How it works". Two reasons: it is not a teaching
          note (it is about the country, not the language, which is the line that
          separates this primitive from a Skill Builder), and a word can carry an
          anecdote without carrying teaching notes at all — nesting it would hide
          those. No read-state, no dismiss, no counts, never auto-opened.
          AI-AUTHORED, unverified until reviewer batch J returns. */}
      {/* Verb forms — reference rows until the grammar finishes a form, a
          question from then on. See the FORMS ladder for the mapping. */}
      {step === "see" && <FormsBlock word={word} />}

      {step === "see" && MICRO_ANECDOTES[word.w] && (
        <Card title="Out in the world">
          <p style={{ ...p14, margin: 0 }}>{MICRO_ANECDOTES[word.w]}</p>
        </Card>
      )}

      {step === "write" && (
        <Card title="Write what you can">
          <p style={p14}>
            {traceable.length
              ? <>Trace each character you know. The ones you have not met yet stay in kana —
                  that is correct, not a gap.</>
              : isKanaOnly(word)
              ? <>This one is all kana — there is nothing to unlock. Read it, and put it to work.</>
              : <>Nothing here is ready to write yet. Read it, and it will come back when it is.</>}
          </p>
          {/* Writing is gated to unlocked kanji (§6.4) — the module never asks for
              a character the learner has not met. Stroke-level checking lives in
              the kanji module, which owns the engine and the stroke data. */}
          {/* Real tracing, from the SAME engine as the kanji module — generated
              into this file by build-shared-stroke-engine.py, not reimplemented.
              Calibration is shared through stroke-data-v1, so the handwriting
              floor set in the kanji module applies here untouched. */}
          {traceable.length > 0 && (
            <StrokePractice
              chars={traceable}
              modId={"vocab:" + word.w}
              progress={{}}
              onProgress={() => setWrote(true)}
            />
          )}
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginTop: 12 }}>
            <Primary onClick={() => setStep("sentence")}>
              {traceable.length ? "Done writing" : "Next"}
            </Primary>
          </div>
        </Card>
      )}

      {step === "sentence" && (
        <Card title="Use it in a sentence">
          <p style={p14}>
            Write one sentence using {word.w}. Say something true — it sticks better than
            something invented to fit.
          </p>
          {/* TODO(post-Phase 0): grade this via the checker once SYSTEM_PROMPT is
              unfrozen. Self-assessment until then — no new prompt surface. */}
          <textarea rows={3} aria-label={`Your sentence using ${word.w}`} style={{
            width: "100%", boxSizing: "border-box", font: `1.0625rem ${T.jpFont}`,
            padding: 10, borderRadius: 8, border: `1px solid ${T.hairline}`,
            background: T.sheet, color: T.ink, resize: "vertical",
          }} />
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginTop: 12 }}>
            <Primary onClick={() => onDone({ wrote, sentence: true })}>Done</Primary>
            {canSkipSentence && (
              <Secondary onClick={() => onDone({ wrote, sentence: false })}>
                Skip this time
              </Secondary>
            )}
          </div>
          {canSkipSentence && (
            <p style={{ ...p14, color: T.sub, marginTop: 10 }}>
              Skipping is fine — you just won't earn the AP for it.
            </p>
          )}
        </Card>
      )}
    </div>
  );
}

// ————— Review area (§6.8) —————
function Review({ items, known, onOpen, onUnlearn }) {
  const [q, setQ] = useState("");
  const shown = items.filter(({ word }) =>
    !q || word.w.includes(q) || (word.m || "").toLowerCase().includes(q.toLowerCase()));
  if (!items.length) return <Empty>Nothing here yet. Words arrive once you have practised them.</Empty>;
  return (
    <div>
      <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Find a word"
             aria-label="Find a word" style={{
        width: "100%", boxSizing: "border-box", font: `0.9375rem ${T.uiFont}`, padding: "9px 12px",
        borderRadius: 8, border: `1px solid ${T.hairline}`, background: T.sheet,
        color: T.ink, marginBottom: 14,
      }} />
      {shown.map(({ word }) => (
        <div key={word.w} style={{
          display: "flex", alignItems: "center", gap: 12, padding: "11px 14px",
          border: `1px solid ${T.hairline}`, borderRadius: 10, marginBottom: 8, background: T.sheet,
        }}>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ color: T.ink, lineHeight: 1.9 }}>
              <WordText word={word} known={known} size={20} />
              {isComplete(word, known) && (
                <span title="you can write all of this" style={{ color: T.ok, marginLeft: 8, fontSize: "0.875rem" }}>✓</span>
              )}
            </div>
            <div style={{ font: `0.8125rem ${T.uiFont}`, color: T.sub, overflow: "hidden", textOverflow: "ellipsis" }}>
              {word.m}
            </div>
          </div>
          <button onClick={() => onOpen({ word, pend: [] })} style={linkBtn}>practise</button>
          <button onClick={() => onUnlearn(word)} style={{ ...linkBtn, color: T.shu }}>unlearn</button>
        </div>
      ))}
    </div>
  );
}

// ————— Small pieces —————
const p14 = { font: `0.875rem/1.6 ${T.uiFont}`, color: T.ink, margin: "0 0 4px" };

// Step labels are long ("Step 6 · Invitations, desire & intention"). In the
// vocabulary module the learner wants a rough where-abouts, not the full title.
function stepShort(s) {
  if (!s) return "later on";
  if (s.startsWith("Checkpoint")) return "a checkpoint";
  if (s.startsWith("Stress")) return "the N4 stress test";
  const m = s.match(/^Step (\d+)/);
  return m ? `Step ${m[1]}` : s;
}
function Note({ children }) {
  return (
    <p style={{
      font: `0.8125rem/1.6 ${T.uiFont}`, color: T.ink, background: T.noteBg,
      border: `1px solid ${T.note}`, borderRadius: 8, padding: "9px 12px", margin: "10px 0 0",
    }}>{children}</p>
  );
}
const linkBtn = {
  background: "none", border: "none", padding: 4, cursor: "pointer",
  font: `0.8125rem ${T.uiFont}`, color: T.ai, textDecoration: "underline",
};

function Shell({ children }) {
  return (
    <div style={{ background: T.paper, minHeight: "100%", padding: "22px 18px 60px" }}>
      <div style={{ maxWidth: 560, margin: "0 auto" }}>{children}</div>
    </div>
  );
}
function Stat({ label, value, accent }) {
  return (
    <div style={{
      background: accent ? T.noteBg : T.sheet, border: `1px solid ${accent ? T.note : T.hairline}`,
      borderRadius: 10, padding: "8px 14px", minWidth: 84,
    }}>
      <div style={{ font: `600 1.25rem ${T.uiFont}`, color: accent ? T.note : T.ink }}>{value}</div>
      <div style={{ font: `0.75rem ${T.uiFont}`, color: T.sub }}>{label}</div>
    </div>
  );
}
function Tabs({ view, setView, reviewCount }) {
  const tab = (id, label) => (
    <button onClick={() => setView(id)} style={{
      background: "none", border: "none", cursor: "pointer", padding: "8px 2px", marginRight: 18,
      font: `${view === id ? 600 : 400} 0.9375rem ${T.uiFont}`,
      color: view === id ? T.ink : T.sub,
      borderBottom: `2px solid ${view === id ? T.ink : "transparent"}`,
    }}>{label}</button>
  );
  return (
    <nav style={{ borderBottom: `1px solid ${T.hairline}`, marginBottom: 18 }}>
      {tab("today", "New")}
      {tab("review", reviewCount ? "Review" : "Review")}
    </nav>
  );
}
function Queue({ title, hint, items, onOpen, badge, known }) {
  if (!items.length) return null;
  return (
    <section style={{ marginBottom: 22 }}>
      <h2 style={{ font: `600 0.9375rem ${T.uiFont}`, color: T.ink, margin: "0 0 2px" }}>
        {title}
        {badge && <span style={{
          marginLeft: 8, background: T.note, color: T.sheet, borderRadius: 999,
          padding: "1px 8px", font: `600 0.6875rem ${T.uiFont}`, verticalAlign: "middle",
        }}>more</span>}
      </h2>
      <p style={{ font: `0.8125rem ${T.uiFont}`, color: T.sub, margin: "0 0 10px" }}>{hint}</p>
      {items.map(({ word, pend }) => (
        <button key={word.w} onClick={() => onOpen({ word, pend })} style={{
          display: "flex", alignItems: "center", gap: 12, width: "100%", textAlign: "left",
          padding: "12px 14px", border: `1px solid ${T.hairline}`, borderRadius: 10,
          marginBottom: 8, background: T.sheet, cursor: "pointer",
        }}>
          <span style={{ color: T.ink, lineHeight: 1.9 }}><WordText word={word} known={known} size={22} /></span>
          <span style={{ flex: 1, font: `0.8125rem ${T.uiFont}`, color: T.sub }}>{word.m}</span>
          {pend.length > 0 && (
            <span style={{ font: `1.125rem ${T.jpFont}`, color: T.note }}>{pend.join("")}</span>
          )}
        </button>
      ))}
    </section>
  );
}
function Card({ title, children }) {
  return (
    <section style={{
      background: T.sheet, border: `1px solid ${T.hairline}`, borderRadius: 12,
      padding: "18px 18px 20px", marginBottom: 14,
    }}>
      <h2 style={{ font: `600 0.9375rem ${T.uiFont}`, color: T.ink, margin: "0 0 8px" }}>{title}</h2>
      {children}
    </section>
  );
}
function Primary({ children, onClick }) {
  return <button onClick={onClick} style={{
    background: T.ink, color: T.sheet, border: "none", borderRadius: 8,
    padding: "10px 18px", font: `600 0.875rem ${T.uiFont}`, cursor: "pointer",
  }}>{children}</button>;
}
function Secondary({ children, onClick }) {
  return <button onClick={onClick} style={{
    background: T.sheet, color: T.ink, border: `1px solid ${T.hairline}`, borderRadius: 8,
    padding: "10px 18px", font: `500 0.875rem ${T.uiFont}`, cursor: "pointer",
  }}>{children}</button>;
}
function Empty({ children }) {
  return <p style={{
    font: `0.875rem ${T.uiFont}`, color: T.sub, background: T.sheet, borderRadius: 10,
    border: `1px dashed ${T.hairline}`, padding: "18px 16px", textAlign: "center",
  }}>{children}</p>;
}
